import pandas as pd
import json

DATA_FILE = "/home/chs/Work/tga_plot/eval/inputs_b/caox.csv"

# Read the CSV file
df = pd.read_csv(DATA_FILE)

# Filter data for x range 100 to 900 °C
mask = (df["Temperature (°C)"] >= 100) & (df["Temperature (°C)"] <= 900)
filtered_df = df[mask].copy()

# Find residue at 900 °C (or closest point)
residue_mask = (df["Temperature (°C)"] >= 895) & (df["Temperature (°C)"] <= 905)
if not residue_mask.any():
    # Fallback: find the point closest to 900
    idx_closest = (df["Temperature (°C)"] - 900).abs().idxmin()
    residue_temp = df.loc[idx_closest, "Temperature (°C)"]
    residue_weight = df.loc[idx_closest, "Weight (%)"]
else:
    # Take the last point in the range or average? Let's take the one closest to 900 within mask
    sub_df = df[residue_mask]
    idx_closest = (sub_df["Temperature (°C)"] - 900).abs().idxmin()
    residue_temp = df.loc[idx_closest, "Temperature (°C)"]
    residue_weight = df.loc[idx_closest, "Weight (%)"]

# Prepare series data
series_data = []
for _, row in filtered_df.iterrows():
    series_data.append([float(row["Temperature (°C)"]), float(row["Weight (%)"])])

# Build ECharts option
option = {
    "title": {
        "text": "TGA Weight Curve",
        "left": "center",
        "top": 10,
        "textStyle": {
            "fontFamily": "Noto Sans CJK KR",
            "fontSize": 16
        }
    },
    "tooltip": {
        "trigger": "axis",
        "formatter": "{a}<br/>Temperature: {b} °C<br/>Weight: {c} %"
    },
    "grid": {
        "left": "10%",
        "right": "10%",
        "bottom": "15%",
        "containLabel": True
    },
    "xAxis": {
        "name": "Temperature (°C)",
        "type": "value",
        "min": 100,
        "max": 900,
        "nameLocation": "middle",
        "nameGap": 30,
        "nameTextStyle": {
            "fontFamily": "Noto Sans CJK KR",
            "fontSize": 12
        },
        "axisLabel": {
            "fontFamily": "Noto Sans CJK KR",
            "fontSize": 10
        }
    },
    "yAxis": {
        "name": "Weight (%)",
        "type": "value",
        "nameLocation": "middle",
        "nameGap": 40,
        "nameTextStyle": {
            "fontFamily": "Noto Sans CJK KR",
            "fontSize": 12
        },
        "axisLabel": {
            "fontFamily": "Noto Sans CJK KR",
            "fontSize": 10
        }
    },
    "series": [
        {
            "name": "Weight (%)",
            "type": "line",
            "data": series_data,
            "showSymbol": False,
            "lineStyle": {
                "width": 2,
                "color": "#1f77b4"
            },
            "markPoint": {
                "data": [
                    {
                        "coord": [residue_temp, residue_weight],
                        "symbolSize": 8,
                        "itemStyle": {
                            "color": "#d62728"
                        },
                        "label": {
                            "show": True,
                            "formatter": f"Residue @ 900°C: {residue_weight:.2f}%",
                            "position": "top",
                            "fontFamily": "Noto Sans CJK KR",
                            "fontSize": 11,
                            "color": "#d62728"
                        }
                    }
                ]
            }
        }
    ]
}

output = {
    "figures": [
        {
            "name": "tga_weight_curve",
            "option": option,
            "width": 614,
            "height": 442,
            "dpi": 300,
            "formats": ["png"]
        }
    ]
}

print(json.dumps(output))
